\set ON_ERROR_STOP on
begin;
select public.system_package_rehearsal(jsonb_build_object('kind','bundle','systems',jsonb_build_array(jsonb_build_object('key','offering','name','Staff offering','definition',public.offering_package_definition('private_staff_requests','1.0.0')))));

create function pg_temp.osv_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Offering lineage: %',label; end if; end $$;
insert into public.users(id,email,verified_at) values('cf000000-0000-4000-8000-000000000001','offering-operator@example.test',now()),('cf000000-0000-4000-8000-000000000002','offering-owner@example.test',now()),('cf000000-0000-4000-8000-000000000003','offering-reviewer@example.test',now());
insert into public.super_admins(user_id,email) values('cf000000-0000-4000-8000-000000000001','offering-operator@example.test');
insert into public.workspaces(id,kind,name,created_by) values('cf000000-0000-4000-8000-000000000010','agency','Real fictional platform agency','cf000000-0000-4000-8000-000000000001'),('cf000000-0000-4000-8000-000000000011','customer','Offering owner','cf000000-0000-4000-8000-000000000002');
insert into public.workspace_memberships(workspace_id,user_id,role,created_by) values('cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000001','owner','cf000000-0000-4000-8000-000000000001'),('cf000000-0000-4000-8000-000000000011','cf000000-0000-4000-8000-000000000002','owner','cf000000-0000-4000-8000-000000000002');
select public.set_platform_workspace('offering-operator@example.test','strelva_agency','cf000000-0000-4000-8000-000000000010');
insert into public.workspaces(id,kind,name,created_by) values('cf000000-0000-4000-8000-000000000012','customer','Historical offering business','cf000000-0000-4000-8000-000000000002');
insert into public.workspace_memberships(workspace_id,user_id,role,created_by) values('cf000000-0000-4000-8000-000000000012','cf000000-0000-4000-8000-000000000002','owner','cf000000-0000-4000-8000-000000000002');
create temporary table osv_legacy(id uuid,resources jsonb);
insert into osv_legacy select i.id,i.native_resources from public.prepare_staff_request_offering('cf000000-0000-4000-8000-000000000012','cf000000-0000-4000-8000-000000000002','offering-owner@example.test','legacy-native-staff',repeat('e',64),'{}','{"kind":"customer_operated","providerName":"Own team"}',array['submit_requests','review_requests'],array['staff_app','business_workspace']) i;
select pg_temp.osv_assert((select source_revision_id is null and version_lineage_id is null from public.offering_installations where id=(select id from osv_legacy)),'pre-registration native setup keeps working without inventing creator lineage');
do $$ declare app uuid; installation uuid;begin
 select id,(resources->0->>'id')::uuid into installation,app from osv_legacy;
 perform public.rehearse_application_candidate(app,'cf000000-0000-4000-8000-000000000012','cf000000-0000-4000-8000-000000000002','offering-owner@example.test',0);
 perform public.publish_application_candidate(app,'cf000000-0000-4000-8000-000000000012','cf000000-0000-4000-8000-000000000002','offering-owner@example.test',0,0);
 perform public.activate_offering('cf000000-0000-4000-8000-000000000012',installation,'cf000000-0000-4000-8000-000000000002','offering-owner@example.test',1);
end $$;
select public.register_offering_package_source('offering-operator@example.test',id,'1.0.0') from unnest(array['private_staff_requests','customer_inquiry_intake','managed_website_changes']) id;
select pg_temp.osv_assert((select count(*)=3 from public.offering_package_sources),'all three native definitions persist exact source revisions');
select pg_temp.osv_assert((select bool_and(jsonb_array_length(q.evidence)=4 and q.evidence->2->>'status'='passed' and q.human_state='pending') from public.system_revision_qualifications q join public.offering_package_sources s on s.source_revision_id=q.revision_id),'native validators execute and human approval stays required');
select pg_temp.osv_assert(public.migrate_offering_installation_versions('offering-operator@example.test')=1,'explicit historical adoption records existing active native release without republishing it');
select pg_temp.osv_assert(public.migrate_offering_installation_versions('offering-operator@example.test')=0,'historical adoption is idempotent');
select pg_temp.osv_assert((select i.source_revision_id is not null and i.version_lineage_id is not null and i.status='active' and i.native_resources=l.resources from public.offering_installations i join osv_legacy l on i.id=l.id),'adoption preserves native resources,status,configuration and record scope');
insert into public.system_revision_reviewers(user_id,policy_version) values('cf000000-0000-4000-8000-000000000003','explicit-fictional-review-policy');
select public.review_system_revision_qualification('cf000000-0000-4000-8000-000000000003','offering-reviewer@example.test',source_revision_id,true,'Reviewed exact frozen native offering command wrapper') from public.offering_package_sources;
select public.register_offering_package_source('offering-operator@example.test',id,'1.0.0') from unnest(array['private_staff_requests','customer_inquiry_intake','managed_website_changes']) id;
select pg_temp.osv_assert((select count(*)=3 from public.offering_package_sources),'source registration retries do not create new revisions');
insert into public.tenants(id,stable_id,site_name,active) values('lineage-site','cf000000-0000-4000-8000-000000000020','Local site',true);
insert into public.memberships(user_id,tenant_id,role,tenant_stable_id) values('cf000000-0000-4000-8000-000000000002','lineage-site','owner','cf000000-0000-4000-8000-000000000020');
insert into public.inquiry_workspaces(id,tenant_id,business_id,state) values('cf000000-0000-4000-8000-000000000021','lineage-site','cf000000-0000-4000-8000-000000000011','{"inquiries":[]}');
do $$ declare owner uuid:='cf000000-0000-4000-8000-000000000002'; business uuid:='cf000000-0000-4000-8000-000000000011'; staff public.offering_installations; inquiry public.offering_installations; website public.offering_installations; binding record; resource jsonb; app uuid; caught text; before_version public.system_versions; begin
 select * into staff from public.prepare_staff_request_offering(business,owner,'offering-owner@example.test','staff-lineage',repeat('a',64),'{}','{"kind":"customer_operated","providerName":"Own team"}',array['submit_requests','review_requests'],array['staff_app','business_workspace']);
 perform pg_temp.osv_assert(staff.source_revision_id is not null and staff.creator_workspace_id='cf000000-0000-4000-8000-000000000010' and staff.version_lineage_id is not null and staff.status='draft','new native staff installation creates immutable persisted Version identity and draft');
 select * into inquiry from public.install_offering(business,owner,'offering-owner@example.test','customer_inquiry_intake','1.0.0','inquiry-lineage',repeat('b',64),'{}','[{"kind":"inquiry_workspace","id":"cf000000-0000-4000-8000-000000000021"}]','{"kind":"customer_operated","providerName":"Own team"}',array['handle_inquiries'],array['inquiry_workspace']);
 select * into binding from public.bind_offering_website(business,owner,'offering-owner@example.test','lineage-site','website-binding',repeat('c',64));
 select * into website from public.install_offering(business,owner,'offering-owner@example.test','managed_website_changes','1.0.0','website-lineage',repeat('d',64),'{}',jsonb_build_array(jsonb_build_object('kind','managed_website','id',binding.id)),'{"kind":"customer_operated","providerName":"Own team"}',array['request_changes'],array['managed_website']);
 perform pg_temp.osv_assert(inquiry.version_lineage_id is not null and website.version_lineage_id is not null and inquiry.source_revision_id<>website.source_revision_id,'inquiry and website native resources install as separate exact source Versions');
 perform pg_temp.osv_assert((select count(*)=3 from public.system_versions where business_workspace_id=business and creator_workspace_id='cf000000-0000-4000-8000-000000000010'),'all installations read from persisted source lineage, never semver projections');
 perform pg_temp.osv_assert((select count(*)=3 from public.system_version_bindings b join public.system_versions v on v.id=b.version_id where v.business_workspace_id=business and b.owner_workspace_id=business),'each offering keeps only its destination business native resource binding');
 app:=(staff.native_resources->0->>'id')::uuid;
 perform public.rehearse_application_candidate(app,business,owner,'offering-owner@example.test',0);
 perform public.publish_application_candidate(app,business,owner,'offering-owner@example.test',0,0);
 update public.system_revision_reviewers set active=false where user_id='cf000000-0000-4000-8000-000000000003';
 select * into before_version from public.system_versions where id=staff.version_lineage_id;
 caught:=null;
 begin perform public.activate_offering(business,staff.id,owner,'offering-owner@example.test',1); exception when others then caught:=sqlerrm;end;
 perform pg_temp.osv_assert(caught='system_revision_not_qualified','native offering activation rechecks withdrawn exact-revision review authority');
 perform pg_temp.osv_assert((select status='draft' and revision=1 from public.offering_installations where id=staff.id) and (select row_revision=before_version.row_revision and current_release is null from public.system_versions where id=staff.version_lineage_id) and not exists(select 1 from public.system_version_releases where version_id=staff.version_lineage_id),'refused activation rolls back offering,current Version and release insert');
 perform pg_temp.osv_assert(public.application_runtime_snapshot(app)->>'release_version'='1','qualification refusal changes no previously owner-published native application release');
 update public.system_revision_reviewers set active=true where user_id='cf000000-0000-4000-8000-000000000003';
 staff:=public.activate_offering(business,staff.id,owner,'offering-owner@example.test',1);
 update public.system_revision_reviewers set active=false where user_id='cf000000-0000-4000-8000-000000000003';
 caught:=null;
 begin perform public.update_offering_configuration(business,staff.id,owner,'offering-owner@example.test',2,'{"displayName":"Refused"}'); exception when others then caught:=sqlerrm;end;
 perform pg_temp.osv_assert(caught='system_revision_not_qualified' and (select configuration='{}' and revision=2 from public.offering_installations where id=staff.id),'active native configuration release also cannot bypass revoked qualification');
 update public.system_revision_reviewers set active=true where user_id='cf000000-0000-4000-8000-000000000003';
 staff:=public.update_offering_configuration(business,staff.id,owner,'offering-owner@example.test',2,'{"displayName":"Our requests"}');
 perform pg_temp.osv_assert((select value='{"displayName":"Our requests"}' from public.system_version_overrides where version_id=staff.version_lineage_id and path='configuration'),'native configuration changes synchronize actual Version override');
 staff:=public.retire_offering(business,staff.id,owner,'offering-owner@example.test',3,'Retire local package');
 perform pg_temp.osv_assert((select lifecycle='paused' from public.systems s join public.system_versions v on v.version_system_id=s.id where v.id=staff.version_lineage_id),'retirement preserves released lineage and resources while pausing the System');
 perform pg_temp.osv_assert((select state->'inquiries'='[]' from public.inquiry_workspaces where id='cf000000-0000-4000-8000-000000000021'),'source adoption copies no inquiry records');
end $$;
rollback;
